const DHIKR={subhan:{n:'سبحان الله',t:'سُبْحَانَ اللَّهِ',a:'data:audio/wav;base64,'},hamd:{n:'الحمد لله',t:'الْحَمْدُ لِلَّهِ',a:'data:audio/wav;base64,'},akbar:{n:'الله أكبر',t:'اللَّهُ أَكْبَرُ',a:'data:audio/wav;base64,'},salawat:{n:'صلوا على رسول الله',t:'صَلُّوا عَلَى رَسُولِ اللَّهِ',a:''}};
const TS={on:store.get('tsOn',false),every:(v=>[5,10,15,20,30,60,120].includes(v)?v:15)(store.get('tsEvery',15)),type:(k=>DHIKR[k]?k:'subhan')(store.get('tsType','subhan')),vol:store.get('tsVol',0.6),from:store.get('tsFrom','06:00'),to:store.get('tsTo','22:00')};
let adTab=store.get('adTabSet',false)?store.get('adTab','morning'):(new Date().getHours()>=12?'evening':'morning');const adDone=store.get('adDone',{});
const dayKey=()=>{const d=new Date();return[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
function adState(){if(adDone.d!==dayKey()){adDone.d=dayKey();adDone.morning={};adDone.evening={};store.set('adDone',adDone)}return adDone}
function renderAdhkar(){const st=adState(),list=ADHKAR[adTab],done=st[adTab]||{};const box=$('adList');box.replaceChildren();
let fin=0;list.forEach((a,i)=>{const c=done[i]||0,ok=c>=a.n;if(ok)fin++;const d=document.createElement('div');d.className='dhikr'+(ok?' done':'');
d.innerHTML=`<div class="dhikr-text"></div><div class="dhikr-src"></div><div class="dhikr-row"><button class="dhikr-btn" type="button"></button><span class="dhikr-cnt"></span></div>`;
d.querySelector('.dhikr-text').textContent=a.t;d.querySelector('.dhikr-src').textContent=a.s;
d.querySelector('.dhikr-btn').textContent=ok?'تم ✓':'اضغط للعد';d.querySelector('.dhikr-cnt').textContent=arNum(Math.min(c,a.n))+' / '+arNum(a.n);
d.querySelector('.dhikr-btn').onclick=()=>{if((done[i]||0)>=a.n)return;done[i]=(done[i]||0)+1;st[adTab]=done;store.set('adDone',st);if(navigator.vibrate)navigator.vibrate(15);renderAdhkar()};
box.append(d)});
const pct=Math.round(fin/list.length*100);$('adBar').style.width=pct+'%';$('adProg').textContent='أتممت '+arNum(fin)+' من '+arNum(list.length)+' · '+arNum(pct)+'٪';
document.querySelectorAll('.ad-tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===adTab));
$('adTitle').textContent=adTab==='morning'?'أذكار الصباح':'أذكار المساء';$('adHint').textContent=adTab==='morning'?'من بعد صلاة الفجر حتى الضحى':'من بعد صلاة العصر حتى المغرب'}
document.querySelectorAll('.ad-tab').forEach(b=>b.onclick=()=>{adTab=b.dataset.tab;store.set('adTab',adTab);store.set('adTabSet',true);renderAdhkar()});
