(function autoTab(){const h=new Date().getHours();if(!store.get('adTabSet',false)){adTab=h>=12?'evening':'morning'}})();

/* تسجيلات التسبيح مضمنة داخل التطبيق وتعمل دون إنترنت. */
function tsSound(){return DHIKR[TS.type].a}
function speakSalawat(volume){
if(window.NativeAlarms&&NativeAlarms.previewSalawat){NativeAlarms.previewSalawat(volume);return}
if(!('speechSynthesis' in window)||typeof SpeechSynthesisUtterance==='undefined'){notify('محرك النطق العربي غير متاح على هذا الجهاز');return}
const utterance=new SpeechSynthesisUtterance('صَلُّوا عَلَى رَسُولِ اللَّهِ');utterance.lang='ar';utterance.volume=Math.max(0,Math.min(1,volume));
const voice=speechSynthesis.getVoices().find(v=>/^ar([-_]|$)/i.test(v.lang));if(voice){utterance.voice=voice;utterance.lang=voice.lang}
utterance.onerror=()=>notify('تعذّر تشغيل الصوت العربي؛ تحقّق من تثبيت صوت عربي في الجهاز');speechSynthesis.cancel();speechSynthesis.speak(utterance)
}
function playDhikr(volume){if(TS.type==='salawat'){speakSalawat(volume);return}try{const a=new Audio(tsSound());a.volume=Math.max(0,Math.min(1,volume));a.play().catch(()=>notify('اضغط مرة أخرى للسماح بالصوت'))}catch(error){notify('تعذّر تشغيل الصوت')}}
function inWindow(d){const hm=d.getHours()*60+d.getMinutes(),p=x=>{const[h,m]=x.split(':').map(Number);return h*60+m},a=p(TS.from),b=p(TS.to);return a<=b?hm>=a&&hm<=b:hm>=a||hm<=b}
function tsFire(){if(!inWindow(new Date()))return;playDhikr(TS.vol);
if(!window.NativeAlarms&&'Notification' in window&&Notification.permission==='granted'){try{new Notification(DHIKR[TS.type].n,{body:DHIKR[TS.type].t,silent:true})}catch(e){}}}
let tsTimer=null;function tsSchedule(){clearInterval(tsTimer);tsTimer=null;if(window.NativeAlarms&&NativeAlarms.configureDhikr){NativeAlarms.configureDhikr(TS.on,TS.every,TS.type,TS.vol,TS.from,TS.to)}
if(TS.on&&!window.NativeAlarms)tsTimer=setInterval(tsFire,TS.every*60000);const label='يعمل كل '+arNum(TS.every>=60?(TS.every/60)+' ساعة':TS.every+' دقيقة');$('tsState').textContent=TS.on?(window.NativeAlarms?label+' في الخلفية · يتطلب أذونات أندرويد':label+' أثناء بقاء الصفحة مفتوحة'):'متوقف'}
function tsSync(){$('tsOn').checked=TS.on;$('tsEvery').value=TS.every;$('tsType').value=TS.type;$('tsVol').value=TS.vol;$('tsFrom').value=TS.from;$('tsTo').value=TS.to}
$('tsEvery').innerHTML=[[5,'كل ٥ دقائق'],[10,'كل ١٠ دقائق'],[15,'كل ربع ساعة'],[20,'كل ثلث ساعة'],[30,'كل نصف ساعة'],[60,'كل ساعة'],[120,'كل ساعتين']].map(([v,t])=>`<option value="${v}">${t}</option>`).join('');
$('tsType').innerHTML=Object.entries(DHIKR).map(([k,v])=>`<option value="${k}">${v.n}</option>`).join('');
const tsSet=(k,v,sk)=>{TS[k]=v;store.set(sk,v);tsSchedule()};
$('tsOn').onchange=async e=>{if(e.target.checked&&!window.NativeAlarms&&'Notification' in window&&Notification.permission==='default')await Notification.requestPermission().catch(()=>{});tsSet('on',e.target.checked,'tsOn');if(e.target.checked)notify(window.NativeAlarms?'سيعمل التسبيح في الخلفية':'يعمل التسبيح أثناء فتح التطبيق فقط في المتصفح')};
$('tsEvery').onchange=e=>tsSet('every',+e.target.value,'tsEvery');$('tsType').onchange=e=>tsSet('type',e.target.value,'tsType');$('tsVol').oninput=e=>{TS.vol=+e.target.value;store.set('tsVol',TS.vol)};$('tsVol').onchange=()=>tsSchedule();$('tsFrom').onchange=e=>tsSet('from',e.target.value,'tsFrom');$('tsTo').onchange=e=>tsSet('to',e.target.value,'tsTo');
$('tsTest').onclick=()=>playDhikr(TS.vol);
tsSync();tsSchedule();renderAdhkar();
const settingsPage=$('settings'),proToggle=$('proModeToggle'),settingsSearch=$('settingsSearch'),tsVolPct=$('tsVolPct');
function applyProMode(enabled){const active=!!enabled;store.set('proMode',active);if(proToggle)proToggle.checked=active;if(settingsPage)settingsPage.classList.toggle('pro-mode',active);updateProDiagnostics()}
function updateProDiagnostics(){const badge=$('diagBridgeBadge'),detail=$('diagBridgeDetail');if(!badge||!detail)return;const bridge=window.NativeAlarms;if(!bridge){badge.textContent='غير متصل بأندرويد';badge.classList.add('warn');detail.textContent='وضع المتصفح: لا تتوفر جدولة أندرويد أو حالة أذوناته.';['diagExact','diagNotifications','diagFullscreen','diagBattery'].forEach(id=>{if($(id))$(id).textContent='غير متاح'});if($('diagBatteryHint'))$('diagBatteryHint').textContent='حالة البطارية غير متاحة في وضع المتصفح.';if($('diagLastAlarm'))$('diagLastAlarm').textContent='آخر حالة للجدولة: وضع المتصفح';return}
const exact=bridge.canScheduleExactAlarms?bridge.canScheduleExactAlarms():true,notifications=bridge.canPostNotifications?bridge.canPostNotifications():true,fullscreen=bridge.canUseFullScreenIntent?bridge.canUseFullScreenIntent():true,battery=bridge.isIgnoringBatteryOptimizations?bridge.isIgnoringBatteryOptimizations():null;
if($('diagExact'))$('diagExact').textContent=exact?'مسموح':'يحتاج مراجعة';if($('diagNotifications'))$('diagNotifications').textContent=notifications?'مسموحة':'محظورة';if($('diagFullscreen'))$('diagFullscreen').textContent=fullscreen?'مسموح':'غير مفعّل';if($('diagBattery'))$('diagBattery').textContent=battery===null?'غير متاح':(battery?'مستثنى':'قد يقيّد الخلفية');
const batteryHint=$('diagBatteryHint');if(batteryHint){batteryHint.textContent=battery===false?'إذا تأخر الأذان أو الذكر على Samsung أو Xiaomi أو Oppo، راجع إعدادات بطارية الشركة واسمح للتطبيق بالعمل في الخلفية والتشغيل التلقائي إن كان الخيار متاحًا. فتح إعدادات البطارية لا يعطّل الحماية تلقائيًا.':battery===true?'لا يظهر تقييد عام لتحسين البطارية؛ قد تظل هناك قيود خاصة بالشركة المصنّعة.':'تعذّر التحقق من حالة تحسين البطارية على هذا الجهاز.';}
const ready=exact&&notifications&&fullscreen;badge.textContent=ready?'حالة الأذونات جيدة':'توجد أذونات تحتاج مراجعة';badge.classList.toggle('warn',!ready);detail.textContent='الحالة الفعلية تُقرأ من أندرويد عند فتح الإعدادات والعودة إليها.';let diag={};try{diag=JSON.parse(bridge.getAlarmDiagnostics?bridge.getAlarmDiagnostics():'{}')}catch(error){}const reason=diag.lastAlarmDroppedReason||diag.prayerAlarmScheduleStatus||'لا توجد بيانات بعد';if($('diagLastAlarm'))$('diagLastAlarm').textContent='آخر حالة للجدولة: '+String(reason)}
if(proToggle)proToggle.addEventListener('change',e=>{applyProMode(e.target.checked);notify(e.target.checked?'تم تفعيل الوضع الاحترافي':'تم الرجوع للوضع البسيط')});
if(settingsSearch)settingsSearch.addEventListener('input',e=>{const q=e.target.value.trim().toLocaleLowerCase();settingsPage?.classList.toggle('searching',q.length>0);settingsPage?.querySelectorAll('.setting').forEach(row=>row.classList.toggle('is-hidden',!!q&&!row.textContent.toLocaleLowerCase().includes(q)));settingsPage?.querySelectorAll('.settings-accordion').forEach(group=>{const visible=[...group.querySelectorAll('.setting')].some(row=>!row.classList.contains('is-hidden'));group.classList.toggle('search-empty',!!q&&!visible);if(q&&visible)group.open=true})});
function updateTsVolumePercent(){if(tsVolPct)tsVolPct.textContent=Math.round((Number(TS.vol)||0)*100)+'%'}$('tsVol')?.addEventListener('input',updateTsVolumePercent);
$('diagExactButton')?.addEventListener('click',()=>window.NativeAlarms?.requestExactAlarmAccess?.());$('diagNotificationButton')?.addEventListener('click',()=>window.NativeAlarms?.openNotificationSettings?.());$('diagFullscreenButton')?.addEventListener('click',()=>window.NativeAlarms?.requestFullScreenIntentAccess?.());$('diagBatteryButton')?.addEventListener('click',()=>window.NativeAlarms?.openBatteryOptimizationSettings?.());
$('diagTestAdhanButton')?.addEventListener('click',()=>{const bridge=window.NativeAlarms;if(!bridge?.preview){notify('اختبار الخلفية متاح داخل تطبيق أندرويد فقط');return}if(bridge.isAdhanPlaying?.()){notify('يوجد أذان فعلي قيد التشغيل؛ لم نوقفه');return}if(bridge.isAdhanPlaybackActive?.())bridge.stopPreview?.();else bridge.preview(S.adhanSound||'doha');notify('تم إرسال طلب اختبار تشغيل الأذان')});
window.refreshAlarmPermissionStatus=updateProDiagnostics;applyProMode(store.get('proMode',false));updateTsVolumePercent();


